    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '맞는 말일수록 내 문제라는 확인을 받는 느낌'이라고 한 것이 '자신이 근본적으로 결함이 있고 드러나면 사랑받지 못할 것'이라는 도식 정의와 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '더 잘해야 했는데'라는 생각이 먼저 든다고 한 것은 '괜찮고 문제없는 모습만 보여줘야 한다'는 규칙이 작동하는 모습이며, 회사 상황 사례에서 보고서 오류 시 과도하게 사과하는 행동과 동일 패턴."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/1"],
      "relevance": "연인이 서운함을 표현했을 때 '내가 뭘 잘못하고 있나'라는 반응이 '부족한 모습을 보이면 사람들이 실망해서 떠날 것'이라는 부정적 가정과 연결됨. 상황 사례에서 연인의 표현 직후 이별을 암시한 행동이 이 가정이 작동한 결과."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '오래전부터 상황을 붙잡으려고 애써온 방식'이라고 재구성한 것이 '밝고 문제없는 모습을 유지하며 힘든 감정을 혼자 삭히는' 대처 전략과 일치함. 성장 배경에서 감추도록 요구받은 경험이 이 전략의 기원."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '뭐가 잘못되면 바로 내가 부족해서라는 생각이 먼저 떠올라요'라고 한 것이 '상대가 지적하기 전에 먼저 자신을 깎아내리는' 대처 전략과 직접 연결됨. 팀 회의 오류 상황 사례에서 필요 이상으로 사과한 행동이 이 전략의 구체적 예시."
    }
  ]
}

